// Retell's custom-function payload is generally flatter than Vapi's:
// { name, args, call }. Verify against what your Retell dashboard
// actually sends once the tool is configured, and adjust here if not.
const headers = $input.first().json.headers || {};
const secret = process.env.VOICE_TOOL_SECRET;
if (secret && headers['x-tool-secret'] !== secret) {
  throw new Error('Invalid tool secret.');
}

const body = $input.first().json.body || {};
const args = body.args || body.parameters || {};

const date = (args.date || '').toString().trim();
if (!date) throw new Error('"date" argument is required (YYYY-MM-DD).');

return [{ json: { date } }];

const BUSINESS_START = 9;
const BUSINESS_END = 17;
const SLOT_MINUTES = 60;

const rows = $input.all().map((i) => i.json).filter((r) => r.due_at);
const busy = rows.map((r) => ({
  start: new Date(r.due_at).getTime(),
  end: new Date(r.end_at || r.due_at).getTime(),
}));

const { date } = $('Parse Availability Request').first().json;
const available = [];

for (let hour = BUSINESS_START; hour < BUSINESS_END; hour += SLOT_MINUTES / 60) {
  const slotStart = new Date(`${date}T${String(Math.floor(hour)).padStart(2, '0')}:${hour % 1 ? '30' : '00'}:00`);
  const slotEnd = new Date(slotStart.getTime() + SLOT_MINUTES * 60000);
  const overlaps = busy.some((b) => slotStart.getTime() < b.end && slotEnd.getTime() > b.start);
  if (!overlaps) {
    available.push(slotStart.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }));
  }
}

const result = available.length
  ? `Available times on ${date}: ${available.join(', ')}.`
  : `No open slots on ${date}.`;

return [{ json: { result } }];

const headers = $input.first().json.headers || {};
const secret = process.env.VOICE_TOOL_SECRET;
if (secret && headers['x-tool-secret'] !== secret) {
  throw new Error('Invalid tool secret.');
}

const body = $input.first().json.body || {};
const args = body.args || body.parameters || {};

const date = (args.date || '').toString().trim();
const time = (args.time || '').toString().trim();
const name = (args.name || '').toString().trim();
const phone = (args.phone || '').toString().trim();
const email = (args.email || '').toString().trim();
const durationMinutes = parseInt(args.duration_minutes, 10) || 60;
const reason = (args.reason || 'Phone booking').toString().trim();

if (!date || !time) throw new Error('"date" and "time" are required.');
if (!name || (!phone && !email)) throw new Error('"name" and either "phone" or "email" are required.');

const dueAt = new Date(`${date}T${time}`);
if (isNaN(dueAt.getTime())) throw new Error('Could not parse the requested date/time.');
const endAt = new Date(dueAt.getTime() + durationMinutes * 60000);

const nameParts = name.split(/\s+/);
return [{
  json: {
    firstName: nameParts[0] || 'Unknown',
    lastName: nameParts.slice(1).join(' ') || '-',
    phone: phone || null,
    email: email || null,
    dueAt: dueAt.toISOString(),
    endAt: endAt.toISOString(),
    subject: reason,
    displayDate: dueAt.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }),
  },
}];

const target = $input.first().json;
if (!target || !target.calendar_id) {
  throw new Error('No calendar connected yet — add one in Settings \u2192 Calendar Integrations first.');
}
const booking = $('Parse Booking Request').first().json;

const gBody = {
  summary: booking.subject,
  start: { dateTime: booking.dueAt },
  end: { dateTime: booking.endAt },
};
if (booking.email) gBody.attendees = [{ email: booking.email, displayName: booking.firstName + ' ' + booking.lastName }];

return [{
  json: {
    ownerUserId: target.owner_user_id,
    calendarId: target.calendar_id,
    url: `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(target.calendar_id)}/events`,
    bodyJson: JSON.stringify(gBody),
  },
}];
